selector{
    position: relative;
    overflow: hidden;
}

selector::before{
    content: "";
    position: absolute;
    width: 700px;
    height: 700px;
    background: #ff7a1a;
    border-radius: 50%;
    filter: blur(250px);
    opacity: 0.12;

    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);

    z-index: 0;
}

selector > *{
    position: relative;
    z-index: 1;
}

.neon-container{
    position: relative;
    overflow: hidden;
}

.neon-container::before{
    content: "";
    position: absolute;
    top: 0;
    left: -30%;
    width: 30%;
    height: 25px;
    background: #ff7a00;
    box-shadow:
        0 0 5px #ff7a00,
        0 0 10px #ff7a00,
        0 0 20px #ff7a00,
        0 0 40px #ff7a00;
    animation: neonLine 4s linear infinite;
    transform: rotate(-20deg);
    z-index: 0;
}

.neon-container > *{
    position: relative;
    z-index: 1;
}

@keyframes neonLine {
    0%{
        transform: translate(-100px, -100px) rotate(-20deg);
    }

    100%{
        transform: translate(120vw, 120vh) rotate(-20deg);
    }
}

